def decimal_number(number: float, num_decimals: int = 3) -> float:
    """ Round float number, it has an accuracy parameter. By default it's 3.

    :param number: float number to round.
    :param num_decimals: integer parameter to define accuracy of round value
    :return: float rounded number with default accuracy level is equal to
        value parameter.
    """

    rounded = int(number * pow(10, num_decimals))

    if num_decimals > 0:
        if rounded / 10 % int(rounded / 10) > 5:
            rounded -= rounded % 10 + 1
        else:
            rounded %= 10

    return float(rounded) / pow(10, num_decimals)


