def dfs(lst: List[str], level: int) -> List[int]:
    if len(lst) == 0:
        return [level]
    lvl_count = list(sum([[1, 0] if '(' in s else [-1, 0] for s in lst.split()], []))
    return [level] + [max([item for item in dfs(lvl_count, max(level, item))])
                      for item in dfs(lvl_count, min(level, item))]


