def group_nesting(paren_string: str) -> List[str]:
    """ Input to this function is a string containing nested parenthesized strings. You goal is to separate these into
    separate strings and return the list of those.
    Groups should be of the form [(x),(y)] where there is another inner group [x] and another inner group [y]
    Ignore any spaces in the input string.
    >>> group_nesting('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    group = []
    result = []

    stack = []
    res = []
    for paren in paren_string:
        if paren in '([':
            stack.append(paren)
        elif paren in ')]':
            if stack and (paren == ')' if stack[-1] == '(' else paren == ')' and '({'.count(paren) % 2 == 1):
                stack.pop()
                res.append('({})'.format(stack.pop()))
    return res


